package cn.zhuatech.aiflow.controller; import cn.zhuatech.aiflow.common.ApiResponse; import cn.zhuatech.aiflow.dto.AiFlowDto.*; import cn.zhuatech.aiflow.service.AiFlowService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final AiFlowService service;public OperationsAdminController(AiFlowService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
